public class MainActivity extends Activity {
  final int NAVY=Color.rgb(8,22,38),PANEL=Color.rgb(17,38,58),BLUE=Color.rgb(44,120,235),CYAN=Color.rgb(45,200,220),ORANGE=Color.rgb(245,160,40),GREEN=Color.rgb(55,190,105),YELLOW=Color.rgb(250,205,70),RED=Color.rgb(225,80,70);
  LinearLayout root,wizard; RigView rig; TextView status,result,stepTitle,help; Spinner qProfile,loadCase,viewMode; EditText L,F,M,stations,layers,actCount,actCapacity,pressure,sf,padW,padL; Button calc,auto; int step=0;
  String[] CASES={"+Z Bending","-Z Bending","+Y Bending","-Y Bending","Pitch +My","Pitch -My","Roll +Mx","Roll -Mx","Yaw +Mz","Yaw -Mz","Combined Z+Pitch"};
  String[] VIEWS={"Sembolik Ağac","Mekanik Rig","BOM"};
  String[] Q={"Elliptic","Uniform","Triangular root-high","Triangular tip-high","Parabolic"};
  String[] ST={"1/6 Problem","2/6 Stations + q(x)","3/6 Whiffletree layers","4/6 Actuator count","5/6 Hardware defaults","6/6 Verify"};
  String[] H={"Yük durumunu seç. Her durum için kuvvet yönleri ve mekanik rig görünümü farklı çizilir.","Station sayısı ve q(x) profili seçildiğinde Fi kuvvetleri otomatik hesaplanır.","Layer 1, 2 veya 3 seç. Ağaç seçilen katman kadar gerçek dallanma gösterir.","Actuator sayısını değiştir. Aktüatörler yeniden yerleşir ve üst branch'lere bağlanır.","Basınç, safety factor, actuator kapasitesi ve load-pad ölçülerini kontrol et.","Sembolik, mekanik ve BOM görünümünü birlikte doğrula."};

  @Override public void onCreate(Bundle b){super.onCreate(b);
    ScrollView sv=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(10),dp(10),dp(10),dp(28));root.setBackgroundColor(NAVY);sv.addView(root);
    root.addView(tx("EFT WHIFFLETREE SMART DESIGNER",24,true,Color.WHITE));root.addView(tx("v1.5 • Scenario-specific rig • Mechanical view • Dynamic BOM",12,false,Color.rgb(180,205,225)));
    LinearLayout top=new LinearLayout(this);top.setOrientation(LinearLayout.HORIZONTAL);
    loadCase=new Spinner(this);loadCase.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,CASES));viewMode=new Spinner(this);viewMode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,VIEWS));top.addView(loadCase,new LinearLayout.LayoutParams(0,dp(52),1));top.addView(viewMode,new LinearLayout.LayoutParams(0,dp(52),1));root.addView(top,lp());
    status=card("Hazır",Color.rgb(13,45,68));root.addView(status,lp());rig=new RigView();root.addView(rig,new LinearLayout.LayoutParams(-1,dp(560)));
    wizard=new LinearLayout(this);wizard.setOrientation(LinearLayout.VERTICAL);wizard.setPadding(dp(10),dp(10),dp(10),dp(10));wizard.setBackground(bg(PANEL,12));root.addView(wizard,lp());
    stepTitle=tx("",18,true,Color.WHITE);help=tx("",13,false,Color.rgb(190,215,232));wizard.addView(stepTitle);wizard.addView(help);
    F=field("Target total load [kN]","305.7");M=field("Target moment [kN·m]","1280");L=field("Tank length [m]","7.6");stations=field("Station count","12");
    wizard.addView(tx("q(x) profile",12,true,Color.rgb(185,210,230)));qProfile=new Spinner(this);qProfile.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,Q));wizard.addView(qProfile,lp());
    layers=field("Whiffletree layer count (1-3)","3");actCount=field("Actuator count (1-8)","4");actCapacity=field("Actuator nominal capacity [kN]","120");pressure=field("Hydraulic pressure [bar]","210");sf=field("Sizing factor","1.50");padW=field("Pad width [mm]","150");padL=field("Pad length [mm]","250");
    auto=new Button(this);auto.setText("AUTO OPTIMIZE ACTUATORS");auto.setOnClickListener(v->{try{Calc c=compute(true);actCount.setText(String.valueOf(c.nAct));preview(c);result.setText("Actuator sayısı optimize edildi: "+c.nAct+"\nMekanik görünüm ve BOM güncellendi.");}catch(Exception e){result.setText("Girişleri kontrol et.");}});wizard.addView(auto,lp());
    calc=new Button(this);calc.setText("HESAPLA + GÖRSELLERİ GÜNCELLE");calc.setOnClickListener(v->calculate());wizard.addView(calc,lp());
    LinearLayout nav=new LinearLayout(this);Button prev=new Button(this),next=new Button(this);prev.setText("← Geri");next.setText("Devam →");nav.addView(prev,new LinearLayout.LayoutParams(0,dp(48),1));nav.addView(next,new LinearLayout.LayoutParams(0,dp(48),1));wizard.addView(nav,lp());prev.setOnClickListener(v->{if(step>0){step--;render();}});next.setOnClickListener(v->{if(step<5){step++;render();}else calculate();});
    result=card("Sembolik, mekanik ve BOM görünümü actuator/layer seçimlerine göre canlı güncellenir.",Color.rgb(12,34,52));root.addView(result,lp());root.addView(card("BOM ön seçimdir; gerçek parça numarası/rating seçimi üretici katalogları ve onaylı yüklar ile doğrulanmalıdır.",Color.rgb(63,45,12)),lp());
    TextWatcher tw=new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){safe();}public void afterTextChanged(Editable e){}};for(EditText e:new EditText[]{F,M,L,stations,layers,actCount,actCapacity,pressure,sf,padW,padL})e.addTextChangedListener(tw);
    android.widget.AdapterView.OnItemSelectedListener lis=new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?>p,View v,int pos,long id){safe();}public void onNothingSelected(android.widget.AdapterView<?>p){}};qProfile.setOnItemSelectedListener(lis);loadCase.setOnItemSelectedListener(lis);viewMode.setOnItemSelectedListener(lis);
    setContentView(sv);render();safe();
  }

  EditText field(String label,String def){wizard.addView(tx(label,12,true,Color.rgb(185,210,230)));EditText e=new EditText(this);e.setText(def);e.setTextColor(Color.WHITE);e.setSingleLine(true);e.setTextSize(16);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);e.setBackground(bg(Color.rgb(25,52,75),8));e.setPadding(dp(10),0,dp(10),0);wizard.addView(e,new LinearLayout.LayoutParams(-1,dp(44)));return e;}
  void render(){stepTitle.setText(ST[step]);help.setText(H[step]);show(F,step==0||step==4);show(M,step==0||step==4);show(L,step==0);show(stations,step==1);qProfile.setVisibility(step==1?View.VISIBLE:View.GONE);show(layers,step==2);show(actCount,step==3);show(actCapacity,step==3||step==4);show(pressure,step==4);show(sf,step==4);show(padW,step==4);show(padL,step==4);auto.setVisibility(step==3?View.VISIBLE:View.GONE);calc.setVisibility(step==5?View.VISIBLE:View.GONE);safe();}
  void show(EditText e,boolean on){int i=wizard.indexOfChild(e);if(i>0)wizard.getChildAt(i-1).setVisibility(on?View.VISIBLE:View.GONE);e.setVisibility(on?View.VISIBLE:View.GONE);}
  void safe(){try{preview(compute(false));}catch(Exception ignored){}}
  void preview(Calc c){rig.set(c,loadCase.getSelectedItemPosition(),viewMode.getSelectedItemPosition());status.setText(String.format(Locale.US,"%s • %s • %d stations • %d layers • %d actuators",CASES[loadCase.getSelectedItemPosition()],VIEWS[viewMode.getSelectedItemPosition()],c.n,c.layers,c.nAct));}
  void calculate(){try{Calc c=compute(false);preview(c);StringBuilder s=new StringBuilder();s.append("ENGINEERING SUMMARY\n");s.append(String.format(Locale.US,"Case: %s\nStations %d | Layers %d | Actuators %d\nΣF %.1f kN | M %.1f kN·m | error %.2f %%\nDesign load %.1f kN | %.1f kN/actuator\nBore %.1f mm @ %.0f bar | LC ≥ %.0f kN\n\n",CASES[loadCase.getSelectedItemPosition()],c.n,c.layers,c.nAct,c.sumF,c.calcM,c.mErr,c.designF,c.actLoad,c.bore,c.pbar,c.lc));s.append("DYNAMIC BOM\n").append(c.bom).append("\nTREE\n").append(c.tree);result.setText(s.toString());}catch(Exception e){result.setText("Geçersiz giriş.");}}

  Calc compute(boolean opt){Calc c=new Calc();c.L=d(L);c.targetF=Math.abs(d(F));c.targetM=d(M);c.n=clamp((int)Math.round(d(stations)),4,16);c.layers=clamp((int)Math.round(d(layers)),1,3);double cap=Math.max(1,d(actCapacity));c.pbar=Math.max(1,d(pressure));c.sf=Math.max(1,d(sf));c.designF=c.targetF*c.sf;int manual=clamp((int)Math.round(d(actCount)),1,8);int minCap=(int)Math.ceil(c.designF/cap);int minTopo=Math.max(1,(int)Math.ceil(c.n/Math.pow(2,c.layers)));c.nAct=opt?clamp(Math.max(minCap,minTopo),1,8):manual;c.actLoad=c.designF/c.nAct;c.bore=Math.sqrt(4*(c.actLoad*1000)/(c.pbar*100000)/Math.PI)*1000;c.lc=std(c.actLoad*1.2);
    c.x=new double[c.n];c.fi=new double[c.n];double[] w=new double[c.n];double sw=0;int q=qProfile.getSelectedItemPosition();for(int i=0;i<c.n;i++){double u=(i+.5)/c.n;c.x[i]=u*c.L;if(q==0)w[i]=Math.sqrt(Math.max(0,1-Math.pow(2*u-1,2)))+.05;else if(q==1)w[i]=1;else if(q==2)w[i]=1.15-u;else if(q==3)w[i]=.15+u;else w[i]=.25+4*u*(1-u);sw+=w[i];}for(int i=0;i<c.n;i++)c.fi[i]=c.targetF*w[i]/sw;
    double desired=Math.abs(c.targetM),base=0;for(int i=0;i<c.n;i++)base+=c.fi[i]*c.x[i];double mean=0;for(double xx:c.x)mean+=xx;mean/=c.n;double den=0;for(double xx:c.x)den+=(xx-mean)*(xx-mean);double delta=desired-base;if(Math.abs(delta)>1e-9&&den>1e-9)for(int i=0;i<c.n;i++)c.fi[i]+=delta*(c.x[i]-mean)/den;boolean neg=false;for(double v:c.fi)if(v<0)neg=true;if(neg){for(int i=0;i<c.n;i++)c.fi[i]=Math.max(.001,c.fi[i]);double ss=0;for(double v:c.fi)ss+=v;for(int i=0;i<c.n;i++)c.fi[i]*=c.targetF/ss;}c.sumF=0;c.calcM=0;for(int i=0;i<c.n;i++){c.sumF+=c.fi[i];c.calcM+=c.fi[i]*c.x[i];}if(c.targetM<0)c.calcM=-c.calcM;c.mErr=Math.abs(c.targetM)>1e-6?100*(c.calcM-c.targetM)/Math.abs(c.targetM):0;
    int branch=c.n,beams=0;for(int l=0;l<c.layers&&branch>1;l++){beams+=branch/2;branch=(branch+1)/2;}c.beams=beams;c.topBranches=branch;c.tree=synth(c);c.bom=bom(c);return c;}
  String synth(Calc c){StringBuilder sb=new StringBuilder();ArrayList<Double> vals=new ArrayList<>();for(double f:c.fi)vals.add(f*c.sf);for(int lev=1;lev<=c.layers&&vals.size()>1;lev++){ArrayList<Double> nx=new ArrayList<>();sb.append("Layer ").append(lev).append(":\n");for(int i=0;i<vals.size();i+=2){if(i+1<vals.size()){double a=vals.get(i),b=vals.get(i+1),sum=a+b;sb.append(String.format(Locale.US," B%d %.1f+%.1f=%.1f kN pivot %.0f/%.0f%%\n",i/2+1,a,b,sum,100*b/sum,100*a/sum));nx.add(sum);}else nx.add(vals.get(i));}vals=nx;}return sb.toString();}
  String bom(Calc c){int beamPins=c.beams*3;int links=c.n+Math.max(0,c.beams-c.topBranches);int clevis=c.n+c.nAct;int bearings=c.n+c.nAct;int anchors=Math.max(4,c.nAct*2);return "Actuator: "+c.nAct+" ea, ≥"+fmt(c.actLoad)+" kN\nLoad cell: "+c.nAct+" ea, ≥"+fmt(c.lc)+" kN\nServo valve/control channel: "+c.nAct+" ea\nActuator spherical bearing: "+c.nAct+" ea\nStation rod-end/spherical bearing: "+c.n+" ea\nWhiffletree beam: "+c.beams+" ea\nPivot/pin set: "+beamPins+" ea\nTie rod/link: "+links+" ea\nClevis: "+clevis+" ea\nLoad pad/saddle: "+c.n+" ea\nHydraulic hose pair: "+c.nAct+" sets\nLVDT/position feedback: "+c.nAct+" ch\nStrongback: 1 assembly\nFloor anchor: "+anchors+" ea\nEmergency pressure dump: 1 set\nDAQ force channels: "+c.nAct+" ch";}

  class RigView extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG),t=new Paint(Paint.ANTI_ALIAS_FLAG);Calc c;int caseIdx=0,mode=0;RigView(){super(MainActivity.this);setBackgroundColor(Color.rgb(5,17,29));t.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));}void set(Calc x,int ci,int m){c=x;caseIdx=ci;mode=m;invalidate();}protected void onDraw(Canvas cn){super.onDraw(cn);if(c==null)return;if(mode==0)drawSymbolic(cn);else if(mode==1)drawMechanical(cn);else drawBom(cn);}
    void tank(Canvas cn,float left,float right,float y){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(52,64,78));cn.drawRoundRect(new RectF(left,y-dp(24),right,y+dp(24)),dp(24),dp(24),p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(Color.LTGRAY);cn.drawRoundRect(new RectF(left,y-dp(24),right,y+dp(24)),dp(24),dp(24),p);}
    void drawCaseArrows(Canvas cn,float left,float right,float y){int n=Math.min(c.n,12);for(int i=0;i<n;i++){float x=left+(right-left)*(i+.5f)/n;boolean up=true,horiz=false;if(caseIdx==1)up=false;if(caseIdx==2||caseIdx==3||caseIdx==8||caseIdx==9)horiz=true;if(caseIdx==4||caseIdx==5)up=(i<n/2)^(caseIdx==5);if(caseIdx==6||caseIdx==7){if(i%2==0)up=caseIdx==6;else up=caseIdx!=6;}p.setColor(BLUE);p.setStrokeWidth(4);if(horiz){float dir=(caseIdx==3||caseIdx==9)?-1:1;if(caseIdx==8||caseIdx==9)dir=(i<n/2?dir:-dir);cn.drawLine(x,y,x+dir*dp(28),y,p);cn.drawLine(x+dir*dp(28),y,x+dir*dp(20),y-dp(6),p);cn.drawLine(x+dir*dp(28),y,x+dir*dp(20),y+dp(6),p);}else{float y2=y+(up?-dp(50):dp(50));cn.drawLine(x,y,x,y2,p);cn.drawLine(x,y2,x-dp(6),y2+(up?dp(8):-dp(8)),p);cn.drawLine(x,y2,x+dp(6),y2+(up?dp(8):-dp(8)),p);}}if(caseIdx==10){p.setColor(RED);p.setStrokeWidth(3);cn.drawLine((left+right)/2,y,(left+right)/2+dp(40),y,p);}}
    ArrayList<float[]> tree(Canvas cn,float left,float right,float tankY){float[] sx=new float[c.n];for(int i=0;i<c.n;i++)sx[i]=left+(float)(c.x[i]/c.L)*(right-left);ArrayList<float[]> nodes=new ArrayList<>();for(int i=0;i<c.n;i++)nodes.add(new float[]{sx[i],tankY+dp(35),(float)(c.fi[i]*c.sf)});float base=tankY+dp(76);for(int lev=1;lev<=c.layers&&nodes.size()>1;lev++){ArrayList<float[]> nx=new ArrayList<>();float yy=base+dp(57)*(lev-1);p.setColor(lev==1?ORANGE:(lev==2?YELLOW:CYAN));p.setStrokeWidth(5);for(int i=0;i<nodes.size();i+=2){if(i+1<nodes.size()){float[]a=nodes.get(i),b=nodes.get(i+1);float sum=a[2]+b[2],px=(a[0]*b[2]+b[0]*a[2])/sum;cn.drawLine(a[0],yy,b[0],yy,p);p.setStrokeWidth(2);cn.drawLine(a[0],a[1],a[0],yy,p);cn.drawLine(b[0],b[1],b[0],yy,p);t.setTextSize(dp(8));t.setColor(Color.WHITE);cn.drawText(String.format(Locale.US,"%.0fkN",sum),px-dp(15),yy-dp(6),t);nx.add(new float[]{px,yy,sum});}else nx.add(nodes.get(i));}nodes=nx;}return nodes;}
    void drawSymbolic(Canvas cn){int w=getWidth();float left=w*.06f,right=w*.95f,y=dp(120);title(cn,"SEMBOLIK • "+CASES[caseIdx]);tank(cn,left,right,y);drawCaseArrows(cn,left,right,y-dp(28));ArrayList<float[]> nodes=tree(cn,left,right,y);float ay=dp(470);for(int a=0;a<c.nAct;a++){float x=w*(a+1f)/(c.nAct+1f);p.setColor(GREEN);p.setStyle(Paint.Style.FILL);cn.drawRect(x-dp(13),ay-dp(34),x+dp(13),ay,p);p.setStyle(Paint.Style.STROKE);p.setColor(Color.WHITE);float tx=nodes.get(Math.min(nodes.size()-1,(int)((long)a*nodes.size()/c.nAct)))[0];cn.drawLine(x,ay-dp(34),tx,nodes.get(Math.min(nodes.size()-1,(int)((long)a*nodes.size()/c.nAct)))[1],p);t.setTextSize(dp(9));cn.drawText("A"+(a+1),x-dp(7),ay+dp(14),t);}}
    void drawMechanical(Canvas cn){int w=getWidth();float left=w*.06f,right=w*.95f,y=dp(125);title(cn,"MEKANIK RIG • "+CASES[caseIdx]);tank(cn,left,right,y);drawCaseArrows(cn,left,right,y-dp(28));ArrayList<float[]> nodes=tree(cn,left,right,y);float floor=dp(520);p.setColor(Color.rgb(85,95,105));p.setStrokeWidth(8);cn.drawLine(left,floor,right,floor,p);for(int a=0;a<c.nAct;a++){float x=w*(a+1f)/(c.nAct+1f);float top=dp(395);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(90,105,120));cn.drawRoundRect(new RectF(x-dp(18),top,x+dp(18),floor-dp(12)),dp(6),dp(6),p);p.setColor(GREEN);cn.drawRect(x-dp(11),top+dp(12),x+dp(11),top+dp(44),p);p.setColor(YELLOW);cn.drawCircle(x,top+dp(2),dp(8),p);p.setColor(ORANGE);cn.drawRect(x-dp(13),top-dp(16),x+dp(13),top-dp(5),p);p.setColor(CYAN);cn.drawCircle(x,top-dp(28),dp(7),p);p.setStyle(Paint.Style.STROKE);p.setColor(Color.WHITE);p.setStrokeWidth(2);float[]nd=nodes.get(Math.min(nodes.size()-1,(int)((long)a*nodes.size()/c.nAct)));cn.drawLine(x,top-dp(28),nd[0],nd[1],p);t.setTextSize(dp(8));t.setColor(Color.WHITE);cn.drawText("LC",x-dp(7),top+dp(34),t);cn.drawText("SB",x-dp(7),top-dp(25),t);cn.drawText("A"+(a+1),x-dp(8),floor+dp(15),t);}t.setTextSize(dp(9));cn.drawText("LC=Load Cell   SB=Spherical Bearing   Orange=Clevis   Grey=Actuator Body",dp(10),dp(553),t);}
    void drawBom(Canvas cn){title(cn,"DINAMIK BOM • "+c.nAct+" ACT • "+c.layers+" LAYER");String[]lines=c.bom.split("\\n");t.setTextSize(dp(10));float y=dp(58);for(int i=0;i<lines.length;i++){p.setStyle(Paint.Style.FILL);p.setColor(i%2==0?Color.rgb(16,40,59):Color.rgb(12,32,49));cn.drawRoundRect(new RectF(dp(8),y-dp(15),getWidth()-dp(8),y+dp(15)),dp(5),dp(5),p);t.setColor(Color.WHITE);cn.drawText(lines[i],dp(16),y+dp(4),t);y+=dp(32);}}
    void title(Canvas cn,String s){t.setColor(Color.WHITE);t.setTextSize(dp(13));cn.drawText(s,dp(10),dp(24),t);t.setTextSize(dp(9));cn.drawText("Stations="+c.n+"  Layers="+c.layers+"  Actuators="+c.nAct+"  Beams="+c.beams,dp(10),dp(42),t);}
  }

  static class Calc{double L,targetF,targetM,pbar,sf,designF,actLoad,bore,lc,sumF,calcM,mErr;int n,layers,nAct,beams,topBranches;double[]x,fi;String tree,bom;}
  double std(double v){double[]a={10,20,25,50,75,100,150,200,250,300,500,750,1000};for(double x:a)if(x>=v)return x;return Math.ceil(v/100)*100;}double d(EditText e){return Double.parseDouble(e.getText().toString().trim().replace(',','.'));}int clamp(int v,int a,int b){return Math.max(a,Math.min(b,v));}String fmt(double v){return String.format(Locale.US,"%.1f",v);}int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}LinearLayout.LayoutParams lp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));return p;}TextView tx(String s,int z,boolean b,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(Typeface.DEFAULT,b?Typeface.BOLD:Typeface.NORMAL);return v;}TextView card(String s,int c){TextView v=tx(s,13,false,Color.WHITE);v.setPadding(dp(10),dp(10),dp(10),dp(10));v.setBackground(bg(c,10));return v;}GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
}
